+fn flat_feed_zs(tp: &camcraft_app::cl::Toolpath) -> Vec<f64> {
+    use camcraft_app::cl::MoveKind;
+    let mut zs: Vec<f64> = Vec::new();
+    for m in &tp.moves {
+        if m.kind == MoveKind::Feed && (m.from.z - m.to.z).abs() < 1e-6 {
+            let z = m.to.z;
+            if zs.last().is_none_or(|prev| (prev - z).abs() > 1e-6) {
+                zs.push(z);
+            }
+        }
+    }
+    zs
+}
